def test_remove_unwanted_requirements():
    assert sanitize_requirements({
        'foo.bar': [
            'foo',
            'ansible',
            'bar',
        ],
        'bar.foo': [
            'pytest',
            'bar',
            'zoo'
        ]
    }) == [
        'foo  # from collection foo.bar',
        'bar  # from collection foo.bar,bar.foo',
        'zoo  # from collection bar.foo'
    ]


def test_preserve_user_requirements():
    """User requirements should be preserved even if they are in EXCLUDE_REQUIREMENTS"""
    # Test that user-specified yamllint and ansible-lint are kept
    assert sanitize_requirements({
        'user': [
            'yamllint',
            'ansible-lint',
            'requests'
        ]
    }) == [
        'yamllint  # from collection user',
        'ansible-lint  # from collection user',
        'requests  # from collection user'
    ]


def test_mixed_user_and_collection_requirements():
    """Requirements that come from both user and collections should be preserved if user wants them"""
    # yamllint and ansible-lint come from both collections (dev deps) and user (explicitly wanted)
    # They should be preserved because user specified them
    # pytest should be filtered because it only comes from collections
    assert sanitize_requirements({
        'some.collection': [
            'pytest',
            'yamllint', 
            'ansible-lint'
        ],
        'user': [
            'yamllint',
            'ansible-lint',
            'custom-package'
        ]
    }) == [
        'yamllint  # from collection some.collection,user',
        'ansible-lint  # from collection some.collection,user',
        'custom-package  # from collection user'
    ]


def test_skip_bad_formats():
    """A single incorrectly formatted requirement should warn, but not block other reqs"""
    assert sanitize_requirements({'foo.bar': [
        'foo',
        'bar'
    ], 'foo.bad': ['zizzer zazzer zuzz']  # not okay
    }) == ['foo  # from collection foo.bar', 'bar  # from collection foo.bar']
